import math

def control(obs):
    m=obs['local_map']; centres=[]
    for key,sgn in [('left_rail',1),('right_rail',-1)]:
        pts=m[key]
        for i,p in enumerate(pts):
            a=pts[max(0,i-1)]; b=pts[min(len(pts)-1,i+1)]
            dx=b[0]-a[0]; dy=b[1]-a[1]; d=math.hypot(dx,dy)
            if d>0:
                centres.append((p[0]+sgn*2*dy/d,p[1]-sgn*2*dx/d))
    ahead=[p for p in centres if p[0]>0.5]
    if not ahead: return (0,0,180)
    x,y=min(ahead,key=lambda p:abs(math.hypot(*p)-4.0))
    k=2*y/(x*x+y*y+1.8*x)
    hd=math.degrees(math.asin(max(-0.65,min(0.65,2.6*k))))
    h=obs['hitch_deg']; hr=math.radians(hd)
    feed=math.degrees(math.atan2(2.75*math.sin(hr),2.6+1.05*math.cos(hr)))
    steer=max(-34,min(34,feed+2.2*(h-hd)))
    return (steer,-0.65 if abs(h)<28 else -0.45,180)

