import math
def interp(points,x):
    for a,b in zip(points,points[1:]):
        if a[0]<=x<=b[0]:
            return a[1]+(b[1]-a[1])*(x-a[0])/max(0.001,b[0]-a[0])
    return None
def control(obs):
    rails=obs['local_map']
    targets=[]
    for i in range(30,151):
        x=i/10
        l=interp(rails['left_rail'],x); r=interp(rails['right_rail'],x)
        if l is not None and r is not None:
            y=(l+r)/2
            targets.append((abs(math.hypot(x,y)-11),x,y))
    if not targets: return (0,0,180)
    _,x,y=min(targets)
    curvature=2*y/(x*x+y*y)
    desired=max(-43,min(43,math.degrees(math.atan(10.2*curvature))))
    h=obs['hitch_deg']
    feed=math.degrees(math.atan(3.9/10.2*math.sin(math.radians(h))))
    steer=max(-42,min(42,feed+1.8*(h-desired)))
    speed=0.95 if abs(h)>18 or abs(desired)>18 else 1.4
    return (steer,-speed,180)

